// HasSongChart applies the HasEdge predicate on the "song_chart" edge.
func HasSongChart() predicate.SongChartRevision {
	return predicate.SongChartRevision(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, false, SongChartTable, SongChartColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasSongChartWith applies the HasEdge predicate on the "song_chart" edge with a given conditions (other predicates).
func HasSongChartWith(preds ...predicate.SongChart) predicate.SongChartRevision {
	return predicate.SongChartRevision(func(s *sql.Selector) {
		step := newSongChartStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.SongChartRevision) predicate.SongChartRevision {
	return predicate.SongChartRevision(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.SongChartRevision) predicate.SongChartRevision {
	return predicate.SongChartRevision(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.SongChartRevision) predicate.SongChartRevision {
	return predicate.SongChartRevision(sql.NotPredicates(p))
}
